settings.custom_css:
selector .subscribe-container .elementor-field-group:not(.elementor-field-type-upload) .elementor-field:not(.elementor-select-wrapper)  {
    border-width: 2px;
    border-color: var(--e-global-color-primary);
    color: var( --e-global-color-text );
}

selector .subscribe-container  .elementor-button[type="submit"] {
    background-color: var(--e-global-color-primary);
    color: #fff;
}

selector .social-links-container svg path{
    fill: black;

}

selector .social-links-container   .elementor-button{
    background-color: #E8E3D4;
}
/** 
active
*/

selector.footer-active{
    background-color: #DBE6ED;
}
selector.footer-active .subscribe-container{
    background-color: #0386AA;
}

selector.footer-active .subscribe-container .elementor-heading-title{
    color: #fff;
}

selector.footer-active .subscribe-container .elementor-field-group:not(.elementor-field-type-upload) .elementor-field:not(.elementor-select-wrapper)  {
    border-color: #fff;
    color: #fff;
}

selector.footer-active .subscribe-container  .elementor-button[type="submit"] {
    background-color: #fff;
    color: var(--e-global-color-primary);
}

selector.footer-active .social-links-container svg path{
    fill: var(--e-global-color-primary);
}

selector.footer-active .social-links-container   .elementor-button{
    background-color: #fff;
}

selector input{
    padding: 21px 170px 21px 35px;
}


selector .elementor-field-type-submit{
    position: absolute;
    top: 16px;
    right: 14px;
    width: auto;
    transition: all .25s ease-in;
}

@media (max-width: 767px) {
    selector input{
        padding: 12px 170px 12px 35px;

    }
    selector .elementor-field-type-submit{
        top: 8px;
    }
}

/** submitted */
selector.submitted .elementor-field-type-submit{
    position: absolute;
    top: 16px;
    left: 14px;
    right: auto;
    width: auto;
    pointer-events: none;
}
selector.submitted input{
    padding: 21px 35px 21px 230px;
}
selector.submitted input::placeholder{
    opacity: 1;
}


selector .elementor-message-success{
    display: none;
}

selector a:hover{
    text-decoration: underline;
}

