selector .mobile-dropdown .mobile-dropdown-items {
    max-height: 0; /* Cambiado de height */
    overflow: hidden; /* Para ocultar el contenido que no cabe */
    transition: max-height 0.3s ease-in-out, visibility 0.3s ease-in-out;
    visibility: hidden;
    flex-wrap: nowrap;
}

/* Estilo para el estado activo */
selector .mobile-dropdown.active .mobile-dropdown-items {
    max-height: 600px; /* Ajusta esto según el contenido máximo esperado */
    visibility: visible;
    margin-bottom: 20px;

}

    selector .mobile-dropdown.active > div.elementor-widget-heading:after{
        transform: rotate(-180deg) ;
    }
}

selector a .elementor-button-icon{
    display: flex;
    height: 26px;
    align-items: center;
    justify-content: center;
}

selector a .elementor-button-icon{
    display: flex;
    height: 26px;
    align-items: center;
    justify-content: center;
}

selector{
    position: fixed;
    right: 30px;
    bottom: 30px;
    z-index: 200;
    width: fit-content;

}

selector{
    max-width: 50px;
    position: relative;
    cursor: pointer;
}

selector {
    width: 50px;
    height: 50px;
}
selector svg circle {
  stroke: #0386aa;
  stroke-width: 1px;
  stroke-linecap: round;
  fill: transparent;
}

selector svg .progress-bar {
  stroke: #000;
  transition: stroke-dashoffset 0 ease-in-out; 
  z-index: 2;
  stroke-width: 2px;
}

selector{
    position: absolute;
    width: 50px;
    height: 50px;
    inset: 0;

}
selector .elementor-icon{
    display: flex;
    align-items: center;
    justify-content: center;
    height: 50px;
}
